#!/usr/bin/env bash
# build_on_glmbox.sh - deploy + run pinlist_v2.py on glm-box (Arch WSL) against
# the three real route traces, emitting /var/lib/insignia/pin-v2.txt.
# CPU-only python; NEVER runs the engine. Usage (local Git Bash):
#   ssh glm-box "wsl -d Arch -- bash -s" < scratch/pinlist/build_on_glmbox.sh
set -euo pipefail

# 1. ship the generator (base64 payload survives ssh->wsl quoting intact)
base64 -d > /var/lib/insignia/pinlist_v2.py <<'EOF64'

EOF64

# 2. self-test in the target environment
python3 /var/lib/insignia/pinlist_v2.py --self-test

# 3. build the v2 pin list from all three real traces (defaults: B=2425, D=321,
#    alpha=0.5, per-layer VRAM mirror). Read the report it prints; then run the
#    engine with the recommended env knobs (PIN_HOST/PIN_DEV are printed).
python3 /var/lib/insignia/pinlist_v2.py \
    --out /var/lib/insignia/pin-v2.txt \
    /var/lib/insignia/route-realtext.txt \
    /var/lib/insignia/route-campaign.txt \
    /var/lib/insignia/early-route-math.txt

wc -lc /var/lib/insignia/pin-v2.txt
echo "done; set INSIGNIA_GLM53_PIN_LIST=/var/lib/insignia/pin-v2.txt plus the"
echo "PIN_HOST / PIN_DEV values printed above when launching the engine."
